(()=>{'use strict';const app=document.getElementById('cup-app'),key='geo34-cup-student-v1';let member={student:null,trainingId:null};try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved?.student&&saved.trainingId)member=saved;}catch{}const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function home(){app.innerHTML='<section class="standalone-cup-title"><p class="eyebrow">GEOGRAPHY CHALLENGE CUP</p><h1>地理闖關挑戰賽</h1><p>不必先完成精熟練習或回傳練習成績，填好資料就能挑戰。</p></section><section class="cup-identity"></section><div class="cards" hidden></div>';const box=app.querySelector('.cup-identity');if(!member.student){box.innerHTML='<h2>填寫學生資料</h2><form id="cup-student-form"><label>班級<input id="cup-student-class" required maxlength="40"></label><label>座號<input id="cup-student-seat" type="number" min="1" max="999" required></label><label>姓名<input id="cup-student-name" required maxlength="40"></label><button class="primary">確認資料</button></form><p id="cup-student-error" role="status"></p>';app.querySelector('#cup-student-form').onsubmit=e=>{e.preventDefault();const className=app.querySelector('#cup-student-class').value.trim().replace(/班$/,'').trim(),seat=String(Number(app.querySelector('#cup-student-seat').value)),name=app.querySelector('#cup-student-name').value.trim();if(!className||!name||!/^\d{1,3}$/.test(seat)||Number(seat)<1){app.querySelector('#cup-student-error').textContent='請完整填寫學生資料。';return;}member={student:{className,seat,name},trainingId:crypto.randomUUID()};sessionStorage.setItem(key,JSON.stringify(member));home();};}else box.innerHTML='<b>'+escape(member.student.className)+'班 '+escape(member.student.seat)+'號 '+escape(member.student.name)+'</b><p>本分頁保留目前學生資料，重新整理可接續挑戰。</p>';window.GEO_CHALLENGE.mount(app,{profile:()=>member,home,escape,openImage:(src,title)=>{document.getElementById('cup-image').src=src;document.getElementById('cup-image-title').textContent=title;document.getElementById('cup-viewer').showModal();}});}document.getElementById('cup-close').onclick=()=>document.getElementById('cup-viewer').close();home();})();
